const fs = require\('fs'\);
const path = require\('path'\);
const glob = require\('glob'\);

// Pattern to find and fix orphaned }\);
function fixVueFile\(filePath\) {
    let content = fs.readFileSync\(filePath, 'utf8'\);
    const originalContent = content;

    // Fix pattern: function...router.get\(...{ }\); followed by orphaned }\);
    // This regex finds cases where we have two consecutive }\); with proper indentation
    content = content.replace\(/\(\\s+}\\s*\\}\\s*\\}\\s*\\\)\\s*;\\s*\\n\\s*\\}\\s*\\\)\\s*;\)/g, \(match\) => {
        // Keep only the first one, remove the orphaned one
        return match.split\('\\n'\)[0];
    }\);

    // Alternative simpler approach: find pattern of two }\); on separate lines
    // where second one is orphaned \(indented more or at statement level\)
    const lines = content.split\('\\n'\);
    const fixedLines = [];

    for \(let i = 0; i < lines.length; i++\) {
        const line = lines[i];
        const nextLine = lines[i + 1];

        // If current line ends with }\); and next line is also }\);
        // and next line's indentation suggests it's orphaned
        if \(line.trim\(\) === '}\);' && nextLine && nextLine.trim\(\) === '}\);'\) {
            fixedLines.push\(line\);
            i++; // Skip the orphaned }\);
            continue;
        }

        // If line is }\); and context suggests it closes a router call
        // followed by orphaned }\);, remove the orphaned one
        if \(line.includes\('}\);'\) && nextLine && nextLine.trim\(\) === '}\);' && 
            !line.includes\('function'\) && !line.includes\('const '\)\) {
            fixedLines.push\(line\);
            i++; // Skip next orphaned line
            continue;
        }

        fixedLines.push\(line\);
    }

    content = fixedLines.join\('\\n'\);

    // Also fix cases where we have closing braces without function
    content = content.replace\(/^    \\}\\\)\\s*;$/gm, '    }'\);

    if \(content !== originalContent\) {
        fs.writeFileSync\(filePath, content, 'utf8'\);
        return true;
    }
    return false;
}

// Find and fix all Index.vue files
glob.sync\('Modules/**/Pages/**/Index.vue'\).forEach\(file => {
    try {
        if \(fixVueFile\(file\)\) {
            console.log\(`✅ Fixed: ${file}`\);
        }
    } catch \(e\) {
        console.error\(`❌ Error fixing ${file}:`, e.message\);
    }
}\);

console.log\('\\n✅ Vue file corrections complete!'\);
