    my \($filepath\) = @_;
    my @lines = read_file\($filepath, chomp => 1\);
    my @fixed;
    my $modified = 0;

    for \(my $i = 0; $i < @lines; $i++\) {
        my $line = $lines[$i];
        my $next = $i + 1 < @lines ? $lines[$i + 1] : '';

        # Pattern: Line ends with just } \(inside a function call context\)
