    title: String,
    fournisseurs: Object,
    filters: Object,
}\);

// Filtres de recherche
const searchFilters = ref\({
    code: props.filters?.code || '',
    libelle: props.filters?.libelle || '',
}\);

// Debounce timer for real-time search
let searchTimeout;

// Real-time search with debounce
const performSearch = \(\) => {
    clearTimeout\(searchTimeout\);
    searchTimeout = setTimeout\(\(\) => {
        search\(\);
    }, 300\);
};

// Modal de suppression
const showDeleteModal = ref\(false\);
const fournisseurToDelete = ref\(null\);
const deleteMode = ref\(false\);
const deactivateMode = ref\(false\);
const activateMode = ref\(false\);

const search = \(\) => {
    router.get\(route\('fournisseurpaiement.index'\), searchFilters.value, {
        preserveState: true,
        preserveScroll: true,
    }\);
};

const resetFilters = \(\) => {
  const emptyFilters = {};
  Object.keys\(searchFilters.value\).forEach\(key => {
    emptyFilters[key] = '';
  }\);
  searchFilters.value = emptyFilters;
  router.get\(route\('quartiers.index'\)\);
};

const confirmDelete = \(fournisseur\) => {
    fournisseurToDelete.value = fournisseur;
    deleteMode.value = true;
    showDeleteModal.value = true;
};

