    if \(fournisseurToDelete.value\) {
        showDeleteLoader\(\);
        router.delete\(route\('fournisseurpaiement.destroy', fournisseurToDelete.value.id\), {
            preserveScroll: true,
            onSuccess: \(\) => {
                showDeleteModal.value = false;
                fournisseurToDelete.value = null;
            },
            onFinish: \(\) => hideLoader\(\),
        }\);
    }
};

const confirmDeactivate = \(fournisseur\) => {
    fournisseurToDelete.value = fournisseur;
    deactivateMode.value = true;
    deleteMode.value = false;
    showDeleteModal.value = true;
};

const confirmActivate = \(fournisseur\) => {
    fournisseurToDelete.value = fournisseur;
    activateMode.value = true;
    deleteMode.value = false;
    showDeleteModal.value = true;
};

const toggleStatus = \(\) => {
    if \(fournisseurToDelete.value\) {
        showDeleteLoader\(\);
        router.put\(route\('fournisseurpaiement.statut', fournisseurToDelete.value.id\), {}, {
            preserveScroll: true,
            onSuccess: \(\) => {
                showDeleteModal.value = false;
                fournisseurToDelete.value = null;
                deactivateMode.value = false;
                activateMode.value = false;
            },
            onFinish: \(\) => hideLoader\(\),
        }\);
    }
};

